def md(text: str) -> NotebookNode:
    """Создает markdown-ячейку notebook из строки."""
    return nbf.v4.new_markdown_cell(text if text.endswith("\n") else text + "\n")


def code(text: str) -> NotebookNode:
    """Создает code-ячейку notebook из строки."""
    return nbf.v4.new_code_cell(text if text.endswith("\n") else text + "\n")


